import pandas as pd

def table_profile(df):
    rows, cols = df.shape
    mask = df.isna()                      # True where a cell is NaN or None
    return {
        'rows': int(rows),
        'cols': int(cols),
        'missing': int(mask.to_numpy().sum()),
        'complete_rows': int((~mask.any(axis=1)).sum()),
    }
